import json, hashlib, datetime, platform, sys, resource
from pathlib import Path
root = Path.cwd()
rounds = {r: json.loads(Path('raw', r + '_RESULTS.json').read_text()) for r in ['R1', 'R2', 'R3', 'R4', 'R5', 'R6', 'R7']}
records = []
for directory in ['code', 'raw', 'sources']:
    for p in sorted(Path(directory).glob('*')):
        if not p.is_file():
            continue
        records.append({'path': str(p), 'bytes': p.stat().st_size, 'sha256': hashlib.sha256(p.read_bytes()).hexdigest()})
for p in sorted(Path('.').glob('PREREG*.json')) + sorted(Path('.').glob('DECOMPOSITION*.json')):
    records.append({'path': str(p), 'bytes': p.stat().st_size, 'sha256': hashlib.sha256(p.read_bytes()).hexdigest()})
manifest = {'created_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'artifacts': records, 'big_arrays': [], 'all_arrays_under_50_MB': True}
Path('ARTIFACT_MANIFEST.json').write_text(json.dumps(manifest, indent=2) + '\n')
result = {'tag': 'XBREAK-hunt-4', 'lane': str(root), 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'parent_goal': 'Action-relevant observations and complete staged treatment decisions at chairside', 'claim_types': ['capability', 'information_link'], 'clinical_recommendation': False, 'algorithm_novelty': 'NOT_ESTABLISHED: known convex bounds, count reconstruction, mixtures and moment supports. Controls match as expected.', 'method_of_gain': 'New source-specific linkage to intraoperative fallback, and changed representation from completed labels to assigned staged pathways. Not new collected patient data.', 'sources': [{'pmid': '27118600', 'doi': '10.1016/j.joen.2016.03.016', 'role': 'marginal and joint diagnostic counts versus chamber bleeding, selected scheduledRCT patients'}, {'pmid': '39325552', 'doi': '10.1111/iej.14144', 'role': 'assigned pathway and preop CBCT x intraoperative fallback, first-appointment time moments'}], 'rounds': {r: {'claim_type': v.get('claim_type'), 'gates': v['gates'], 'raw_file': 'raw/' + r + '_RESULTS.json', 'cost': v.get('cost')} for (r, v) in rounds.items()}, 'main_outputs': {'fallback_risk_observed_categories': rounds['R6']['observed_categories'], 'association_missingness_robust': rounds['R6']['gates']['source_cohort_association'], 'prediction_gain_gate': rounds['R6']['gates']['all_missing_forecast_gain_ge_5percent'], 'first_appointment_saving_conditional_min': rounds['R5']['first_visit_saving_conditional_min'], 'category_order_interval_min': rounds['R7']['query_intervals'][3]['interval_min'], 'clinical_choice': 'UNKNOWN', 'source_complete_panel_AUC': 'FAIL under explicit same-panel semantics, otherwise estimatorUNKNOWN; no source correction'}, 'failed_frozen_version': {'R1': 'Not numerically run; input contract corrected to R1v2 before computation, missing-index categories retained.'}, 'validation_scope': 'Independent numerical implementations and primary-source cross-checks; no independent clinical calibration/validation, no new clinical measurement.', 'cost_limits': {'threads': 4, 'GPU': False, 'largest_observed_maxrss_kib': max((v['cost']['maxrss_kib'] for v in rounds.values())), 'clinical_acquisition_and_reasoning_cost': 'UNKNOWN / NOT_RUN; not zero', 'charged_prior_cost': 'R2..R7 inherit all parent preparation and computations; no full-cost algorithm speedup claimed', 'own_intermediate_limit_bytes': 3 * 1024 ** 3}, 'big_arrays': [], 'manifest': 'ARTIFACT_MANIFEST.json', 'environment': {'python': sys.version, 'platform': platform.platform()}, 'next_operation': 'Measure joint assignment/CBCT/intraoperative haemostasis/fallback/each-visit time/outcome panel on same cases under registered protocol; blinded independent source extraction and prospective validation; no escalation to action recommendation.'}
